source3='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != bg and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            q.append((ny, nx))
            rows = {}
            for y, x in comp:
                rows.setdefault(y, []).append(x)
            longest = 1
            for y, xs in rows.items():
                xs = sorted(xs)
                run = 1
                for i in range(1, len(xs)):
                    if xs[i] == xs[i - 1] + 1:
                        run += 1
                    else:
                        longest = max(longest, run)
                        run = 1
                longest = max(longest, run)
            if longest < 2:
                continue
            maxc = max(x for _, x in comp)
            for y in rows:
                row_last = max(x for x, v in enumerate(grid[y]) if v != bg)
                if row_last == maxc:
                    for x in range(maxc + 1, w):
                        out[y][x] = 1
    return out
'''
