source6='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [any(v != bg for v in row) for row in grid]
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        rows = range(start, r)
        maxc = max(c for y in rows for c, v in enumerate(grid[y]) if v != bg)
        longest = 1
        for y in rows:
            run = 0
            for v in grid[y]:
                if v != bg:
                    run += 1
                    longest = max(longest, run)
                else:
                    run = 0
        if longest < 2:
            continue
        for y in rows:
            last = max((c for c, v in enumerate(grid[y]) if v != bg), default=-1)
            if last == maxc:
                for c in range(last + 1, w):
                    out[y][c] = 1
    return out
'''
